import { Component, Input, SimpleChanges } from '@angular/core';
import { FormGroupComponent } from '../../../../shared/generic-form/form-group/form-group.component';
import { Credito } from '../../../../models/credito.model';
import { DatePipe, NgClass, TitleCasePipe } from '@angular/common';
import { Router } from '@angular/router';
import { UtilsService } from '../../../../services/utils.service';
import { CollapsableComponent } from "../../../../shared/collapsable/collapsable.component";
import { GeneradorExcelService } from '../../../reportes/services/generador-excel.service';

@Component({
    selector: 'app-view-gestiones-cobro',
    imports: [
    NgClass,
    DatePipe,
    CollapsableComponent,
    TitleCasePipe
],
    templateUrl: './view-gestiones-cobro.component.html',
    styleUrl: './view-gestiones-cobro.component.css'
})
export class ViewGestionesCobroComponent {
  @Input() credito!:Credito
  today = new Date()
  
  constructor(
    public router:Router,
    public utils:UtilsService,
    private excelService: GeneradorExcelService,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['credito'] && this.credito.credito_evento_cobros){
      console.log(this.credito.credito_evento_cobros)
      this.credito.credito_evento_cobros.sort((a, b) => new Date(b.fecha??'1900-01-01').getTime() - new Date(a.fecha??'1900-01-01').getTime());
    }
  }

  getBadgeClass(resultado: string): string {
    switch(resultado) {
      case 'NO REALIZADO':
        return 'bg-secondary';
      case 'NO LOCALIZADO':
        return 'bg-danger bg-opacity-20 text-bg-danger';
      case 'LOCALIZADO':
        return 'bg-success bg-opacity-20 text-bg-success';
      case 'PROMESA DE PAGO':
        return 'bg-warning bg-opacity-20 text-dark';
      case 'CONVENIO CON ADEUDO':
        return 'bg-info bg-opacity-20 text-dark';
      case 'CONVENIO AL CORRIENTE':
        return 'bg-info bg-opacity-10 text-bg-info';
      case 'LIQUIDADO':
        return 'bg-success text-white';
      case 'DEFUNCION':
        return 'bg-dark text-white';
      case 'OTRO':
        return 'bg-light text-dark border';
      default:
        return 'bg-light text-dark';
    }
  }

  exportarExcel(){
    this.excelService.exportToExcel(this.credito.credito_evento_cobros!,'gestiones_cobro');
  }
}
